using System.Collections.Generic;
using UnityEngine;

namespace WildLens.Environment
{
    /// <summary>
    /// An open reserve track (a ranger service track, also a footpath) from the trail loop to a destination.
    /// Generated by the scene builder. The trail bike rides fastest on tracks and trails; the board's map draws them.
    /// </summary>
    /// <summary>Trail hierarchy (0.9): roads carry the bike between destinations; footpaths are for walking.</summary>
    public enum TrackKind { Footpath, Road }

    public class ReserveTrack : MonoBehaviour
    {
        public string title = "Track";
        public TrackKind kind = TrackKind.Footpath;
        [SerializeField] private List<Vector3> points = new List<Vector3>();
        [SerializeField] private float width = 2.4f;

        private static readonly List<ReserveTrack> Active = new List<ReserveTrack>();
        public static IReadOnlyList<ReserveTrack> All => Active;

        public IReadOnlyList<Vector3> Points => points;
        public float Width => width;

        public float Length
        {
            get
            {
                float l = 0f;
                for (int i = 1; i < points.Count; i++) l += Vector3.Distance(points[i - 1], points[i]);
                return l;
            }
        }

        public void SetPath(List<Vector3> newPoints, float newWidth)
        {
            points = new List<Vector3>(newPoints);
            width = newWidth;
        }

        private void OnEnable() { if (!Active.Contains(this)) Active.Add(this); }
        private void OnDisable() => Active.Remove(this);

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics() => Active.Clear();

        /// <summary>Horizontal distance from <paramref name="p"/> to the track's centre-line.</summary>
        public float DistanceTo(Vector3 p)
        {
            float best = float.MaxValue;
            Vector2 q = new Vector2(p.x, p.z);
            for (int i = 1; i < points.Count; i++)
            {
                Vector2 a = new Vector2(points[i - 1].x, points[i - 1].z), b = new Vector2(points[i].x, points[i].z);
                Vector2 ab = b - a;
                float t = ab.sqrMagnitude > 0f ? Mathf.Clamp01(Vector2.Dot(q - a, ab) / ab.sqrMagnitude) : 0f;
                best = Mathf.Min(best, Vector2.Distance(q, a + ab * t));
            }
            return best;
        }

        /// <summary>Distance from <paramref name="p"/> to the edge of the track (negative inside it).</summary>
        public float EdgeDistance(Vector3 p) => DistanceTo(p) - width * 0.5f;

        /// <summary>Distance to the nearest track or the trail loop (whichever is closer).</summary>
        public static float DistanceToAnyPath(Vector3 p, TrailPath trail)
        {
            float best = trail != null ? trail.DistanceToTrail(p) : float.MaxValue;
            foreach (var t in Active) best = Mathf.Min(best, t.DistanceTo(p));
            return best;
        }

        private void OnDrawGizmosSelected()
        {
            Gizmos.color = new Color(0.8f, 0.6f, 0.3f);
            for (int i = 1; i < points.Count; i++)
                Gizmos.DrawLine(points[i - 1] + Vector3.up * 0.3f, points[i] + Vector3.up * 0.3f);
        }
    }
}
